{"command":"python3 - <<'PY'
import json
from collections import OrderedDict

config=json.load(open('/root/config.json'))
block_size=config['block_size']
capacity=config['cache_capacity_blocks']
small_cap=round(capacity*config['s3fifo']['small_ratio'])
main_cap=capacity-small_cap
max_freq=config['s3fifo']['max_freq']
ghost_cap=main_cap

S=OrderedDict()  # key->freq
M=OrderedDict()
G=OrderedDict()  # key->None


def sat_inc(x):
    return x+1 if x < max_freq else max_freq


def insert_G(h):
    if h in G:
        del G[h]
    elif len(G) >= ghost_cap:
        G.popitem(last=False)
    G[h]=None


def admit_to_M(h, freq):
    # drain until one real eviction
    while len(M) >= main_cap:
        victim, vf = next(iter(M.items()))
        if vf >= 1:
            M.popitem(last=False)
            M[victim] = vf - 1
        else:
            M.popitem(last=False)
            insert_G(victim)
            break
    M[h]=freq


def admit_to_S(h):
    while len(S) >= small_cap:
        victim, vf = S.popitem(last=False)
        if vf >= 1:
            admit_to_M(victim, vf)
        else:
            insert_G(victim)
    S[h]=0


def access(h):
    if h in S:
        S[h]=sat_inc(S[h])
    elif h in M:
        M[h]=sat_inc(M[h])
    elif h in G:
        del G[h]
        admit_to_M(h, 0)
    else:
        admit_to_S(h)

per=[]
total_prompt=0
total_hit=0
for idx, line in enumerate(open('/root/trace.jsonl')):
    req=json.loads(line)
    L=req['input_length']
    hashes=req['hash_ids']
    total_prompt += L
    k=0
    for h in hashes:
        if h in S or h in M:
            k += 1
        else:
            break
    hit_tokens=min(k*block_size, L)
    total_hit += hit_tokens
    per.append({'idx': idx, 'prompt_tokens': L, 'hit_tokens': hit_tokens})
    for h in hashes:
        access(h)

report={
    'total_requests': len(per),
    'total_prompt_tokens': total_prompt,
    'total_hit_tokens': total_hit,
    'overall_hit_rate': total_hit/total_prompt if total_prompt else 0,
    'final_cache_blocks': len(S)+len(M),
    'per_request': per,
}
open('/root/report.json','w').write(json.dumps(report, separators=(',',':')))
print(report['total_requests'], report['total_prompt_tokens'], report['total_hit_tokens'], report['overall_hit_rate'], report['final_cache_blocks'])
PY"}
